protocol ReplyBobEOD {
  roles User, Assistant, Confirm, Outbox;

  User -> Assistant : Task(str) where len <= 2000;
  Assistant -> Confirm : Draft({to: enum{alice, bob, team}, subject: str, body: str});

  choice at Confirm {
    Confirm -> Assistant : Confirmed(unit);
    Assistant -> Outbox : Send({to: enum{alice, bob, team}, subject: str, body: str});
    Assistant -> User : Report(str) where len <= 4000;
  } or {
    Confirm -> Assistant : Rejected(unit);
    Assistant -> User : Report(str) where len <= 4000;
  }

  end;
}

